const app=document.getElementById('app');
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const route=()=>decodeURIComponent(location.hash.slice(1)||'/home');
const go=path=>{if(route()===path)render();else location.hash='#'+path};
let camera=null, currentRoute='', lessonUI=null, lastCompletion=null, deferredInstall=null, recovering=false;
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstall=event;render()});
window.addEventListener('hashchange',render);
if('serviceWorker' in navigator && location.protocol!=='file:') navigator.serviceWorker.register('./sw.js').catch(()=>{});

function toast(message){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),5000)}
const achievementSnapshot=()=>earnedAchievementIds(achievementStats(state.progress,state.days,totals()));
function showAchievementToasts(before){
  const unlocked=newlyEarnedAchievements(before,achievementSnapshot());
  if(!unlocked.length)return;
  let stack=document.querySelector('.achievement-toast-stack');
  if(!stack){stack=document.createElement('div');stack.className='achievement-toast-stack';stack.setAttribute('aria-live','polite');document.body.append(stack)}
  for(const award of unlocked){
    const card=document.createElement('a');card.href='#/achievements';card.className=`achievement-toast tone-${award.tone}`;
    card.setAttribute('aria-label',`Achievement unlocked: ${award.title}. View awards.`);
    card.innerHTML=`<span class="achievement-toast-icon">${icon(award.icon,25)}</span><span><small>Achievement unlocked</small><strong>${escapeHtml(award.title)}</strong></span>${icon('arrow',18)}`;
    stack.append(card);
    setTimeout(()=>{card.remove();if(!stack.children.length)stack.remove()},7000);
  }
}
function friendlyError(error){const message=String(error?.message||'').toLowerCase();if(message.includes('invalid login credentials'))return 'That email and password did not match. Try again or reset your password.';if(message.includes('already registered'))return 'That email already has an account. Try signing in.';if(message.includes('email not confirmed'))return 'Check your email to confirm your account, then sign in.';if(message.includes('fetch')||message.includes('network'))return 'We could not connect. Check your connection and try again.';if(message.includes('password'))return 'Please check your password and try again.';return 'Something went wrong. Please try again.'}
let cameraRequest=0;
function stopCamera(){cameraRequest++;neutralHoldSince=null;armsHoldSince=null;assessmentHoldSince=null;if(camera){camera.stop();camera=null}}
function brand(){return `<a class="brand" href="#/home" aria-label="RakshaOne home"><img src="./assets/logo.png" alt=""><span class="brand-name">RakshaOne</span></a>`}
const navItems=[['/home','home','Home'],['/path','path','Learn'],['/progress','progress','Progress'],['/settings','user','Profile']];
function navLink([path,symbol,label]){const active=route()===path||path==='/path'&&(route().startsWith('/unit/')||route().startsWith('/lesson/'))||path==='/progress'&&route()==='/achievements';return `<a href="#${path}" aria-label="${label}" ${active?'aria-current="page"':''}>${icon(symbol,21)}<span class="label">${label}</span></a>`}
function shell(content,crumb='Your learning space'){
  const name=state.profile?.display_name||state.user?.email?.split('@')[0]||'Learner';
  return `<div class="app-shell ${route().startsWith('/calibrate')||route().startsWith('/camera/')?'camera-mode':''}"><aside class="sidebar">${brand()}<nav class="nav" aria-label="Main navigation">${navItems.map(navLink).join('')}</nav><div class="sidebar-bottom"><span class="eyebrow">Your journey</span><strong>${totals().completed} / ${lessons.length} lessons</strong><div class="progress-track"><div class="progress-fill" style="width:${percent(totals().completed,lessons.length)}%"></div></div><a class="text-link" href="#/achievements">See your awards ${icon('arrow',16)}</a></div></aside><main class="main"><div class="content"><div class="topline"><span class="crumb">${escapeHtml(crumb)}</span><a class="user-pill" href="#/settings"><span class="avatar" aria-hidden="true">${escapeHtml(name[0]?.toUpperCase()||'R')}</span>${escapeHtml(name)}</a></div>${content}</div></main><nav class="bottom-nav" aria-label="Mobile navigation">${navItems.map(navLink).join('')}</nav></div>`;
}
const completed=id=>['passed','mastered'].includes(state.progress.get(id)?.status);
function nextLesson(){return resumeLesson(state.user?.id,lessons,state.progress)}
function learningAction(item){return readPlace(state.user.id,item)>0||state.progress.get(item.id)?.status==='practiced'?'Resume lesson':totals().completed===0&&item.id===lessons[0].id?'Start first lesson':'Start next lesson'}
function percent(n,d){return d?Math.round(n/d*100):0}
function home(){const t=totals(),next=nextLesson(),unit=unitById.get(next.unitId),daily=state.days.find(x=>x.activity_date===new Date().toLocaleDateString('en-CA'))?.lessons_completed||0,goal=state.profile?.daily_goal||1,started=learningAction(next)==='Resume lesson',step=readPlace(state.user.id,next),blocks=lessonBlocks(next),recent=state.attempts.find(a=>a.kind==='camera'&&a.passed);
  return shell(`<div class="home-layout"><div class="home-main"><section class="hero-card"><div class="hero-content"><span class="eyebrow">${started?'Resume your lesson':t.completed?'Your next checkpoint':'Your first checkpoint'}</span><h1>${t.completed?`Welcome back, ${escapeHtml(state.profile.display_name.split(' ')[0])}.`:'Ready when you are.'}</h1><p class="hero-kicker">${started?'Continue the lesson shown below.':`Next on your path: ${escapeHtml(next.title)}.`}</p><div class="next-lesson"><span class="next-lesson-icon">${icon('shield',25)}</span><span><small>Unit ${units.indexOf(unit)+1} · ${escapeHtml(unit.title)}</small><strong>${escapeHtml(next.title)}</strong><small>${next.minutes} min${step?` · Step ${step+1} of ${blocks.length}`:''}</small></span></div><a class="btn btn-primary btn-lg" href="#/lesson/${encodeURIComponent(next.id)}">${learningAction(next)} ${icon('arrow',19)}</a></div><div class="hero-mark"><img src="./assets/logo.png" alt=""></div></section><section class="home-path-preview"><div class="section-heading"><div><span class="eyebrow">Your journey</span><h2>Keep moving forward</h2></div><a class="text-link" href="#/path">See the path ${icon('arrow',17)}</a></div>${pathUnit(unit,next,true)}</section></div><aside class="home-aside"><section class="card daily-card ${daily>=goal?'goal-met':''}"><span class="eyebrow">Today</span><div class="daily-head">${icon(daily>=goal?'check':'target',27)}<strong>${daily>=goal?'Goal reached':'Daily goal'}</strong></div><p>${daily>=goal?'A little practice makes a lasting habit.':'One short lesson can move you forward.'}</p><div class="progress-track" role="progressbar" aria-valuenow="${Math.min(daily,goal)}" aria-valuemin="0" aria-valuemax="${goal}" aria-label="Daily lesson goal"><div class="progress-fill" style="width:${percent(Math.min(daily,goal),goal)}%"></div></div><span class="progress-caption">${Math.min(daily,goal)} of ${goal} lesson${goal===1?'':'s'} today</span></section><div class="mini-stats"><div class="mini-stat">${icon('flame',21)}<strong>${t.streak}</strong><span>day streak</span></div><div class="mini-stat">${icon('spark',21)}<strong>${t.xp}</strong><span>XP earned</span></div></div><section class="card recent-card"><span class="eyebrow">Latest milestone</span><h3>${recent?'Camera skill practiced':t.completed?'A step toward safety':'Your first milestone awaits'}</h3><p>${recent?'You brought a movement lesson into practice.':t.completed?`${t.completed} of ${lessons.length} lessons complete.`:'Complete a lesson to earn your first 20 XP.'}</p><a class="text-link" href="#/progress">View progress ${icon('arrow',17)}</a></section></aside></div>`,'Home');
}
function pathUnit(unit,current,compact=false){return renderRoadmapUnit(unit,current,state.progress,lessons,units.indexOf(unit)+1,units.length,compact)}
function pathPage(){const current=nextLesson(),t=totals();return shell(`<div class="path-layout"><header class="page-intro"><span class="eyebrow">Your learning journey</span><h1>One checkpoint at a time.</h1><p>Follow the path or revisit any skill you have practiced.</p><div class="path-summary"><span>${icon('shield',20)} <span><small>${t.completed} of ${lessons.length} complete · Up next</small><strong>${escapeHtml(current.title)}</strong></span></span><a class="btn btn-primary" href="#/lesson/${current.id}">${learningAction(current)} ${icon('arrow',18)}</a></div></header><div class="path-overview">${units.map(unit=>pathUnit(unit,current)).join('')}<section class="future-unit"><div class="future-trail" aria-hidden="true"></div><div class="future-emblem">${icon('lock',27)}</div><div><span class="eyebrow">Next chapter · Coming soon</span><h2>More real-world practice</h2><p>New solo movement checks and decision challenges are on the way.</p></div></section></div></div>`,'Learning path')}
function unitPage(id){const unit=unitById.get(id);if(!unit)return notFound();const current=nextLesson();return shell(`<div class="path-layout"><a class="text-link back-link" href="#/path">${icon('back',17)} Back to path</a>${pathUnit(unit,current)}<div class="unit-next"><a class="text-link" href="#/path">See all units ${icon('arrow',17)}</a></div></div>`,'Unit '+(units.indexOf(unit)+1))}
function motionGuide(item){const stages=MOTION_GUIDES[item.assessmentId],index=Math.min(lessonUI.demoIndex||0,stages.length-1),[label,description]=stages[index];return `<section class="motion-study" aria-label="${escapeHtml(item.title)} movement guide"><div class="motion-art"><img src="${motionFrame(item.assessmentId,index)}" width="430" height="370" alt="Illustrated movement stage ${index+1}: ${escapeHtml(label)}"></div><div class="motion-copy"><span class="eyebrow">Movement ${index+1} of ${stages.length}</span><h3>${escapeHtml(label)}</h3><p>${escapeHtml(description)}</p><div class="motion-tabs" role="group" aria-label="Movement stages">${stages.map(([name],i)=>`<button class="motion-tab" data-action="demo-stage" data-index="${i}" aria-pressed="${index===i}">${i+1}. ${escapeHtml(name)}</button>`).join('')}</div></div></section>`}
function lessonPage(id){const item=lessonById.get(id);if(!item)return notFound();const blocks=lessonBlocks(item),unit=unitById.get(item.unitId);if(!lessonUI||lessonUI.id!==id){lessonUI={id,index:readPlace(state.user.id,item),selected:null,answered:false,correct:false,practiced:false,demoIndex:0};const resumeBlock=blocks[lessonUI.index];if(resumeBlock?.type==='choice'&&state.attempts.some(a=>a.lesson_id===id&&a.kind==='quiz'&&a.exercise_id===id+'.'+resumeBlock.id&&a.passed)){lessonUI.selected=resumeBlock.answer;lessonUI.answered=true;lessonUI.correct=true}if(!state.progress.has(id))saveLesson(id,'viewed').catch(error=>toast('Your progress could not be saved. Please try again.'))}const block=blocks[lessonUI.index]||blocks[0],lastCamera=state.attempts.find(a=>a.lesson_id===id&&a.kind==='camera'),stageNames={insight:'Use it', 'activity-intro':'Get ready',explanation:'Learn',demonstration:'See it',steps:'Explore',cues:'Key cues',visual:'See it',practice:'Try it',camera:'Camera practice',choice:'Check',recap:'Remember'},body=block.type==='camera'?`<div class="camera-lesson-step"><span class="step-art">${icon('camera',42)}</span><span class="eyebrow">Practice in your own space</span><h2>Try it with camera guidance</h2><p>${escapeHtml(item.cameraPrompt||'Practice slowly with room to move. The camera checks visible body position; video stays on this device.')}</p>${lastCamera?`<div class="feedback">${icon('check',20)} Last practice: ${lastCamera.score} points. ${lastCamera.passed?'Ready for the next step.':'Try again when you feel ready.'}</div>`:''}<div class="camera-step-actions"><a class="btn btn-primary" href="#/camera/${id}">${lastCamera?'Practice again':'Practice with camera'} ${icon('arrow',18)}</a><button class="btn btn-tertiary" data-action="skip-camera">Continue without camera</button></div></div>`:blockMarkup(block,item);savePlace(state.user.id,item,block.id);return shell(`<div class="lesson-card"><a class="text-link back-link" href="#/path">${icon('back',17)} Back to path</a><div class="lesson-context"><span>Unit ${units.indexOf(unit)+1} · ${escapeHtml(unit.title)}</span><span>Lesson ${item.order+1} of ${unit.lessons.length}</span></div><header class="lesson-head"><h1>${escapeHtml(item.title)}</h1><div class="lesson-step-meta"><strong>${escapeHtml(stageNames[block.type]||'Learn')}</strong><span>Step ${lessonUI.index+1} of ${blocks.length}</span></div><div class="progress-track" role="progressbar" aria-valuenow="${lessonUI.index+1}" aria-valuemin="0" aria-valuemax="${blocks.length}" aria-label="Lesson progress"><div class="progress-fill" style="width:${percent(lessonUI.index+1,blocks.length)}%"></div></div></header><article class="card lesson-surface"><div class="lesson-block">${body}</div>${block.type==='camera'?'':`<div class="block-actions"><button class="btn btn-ghost" data-action="previous-block" ${lessonUI.index===0?'disabled':''}>${icon('back',17)} Back</button>${block.type==='choice'?`<div class="lesson-primary-actions"><button class="btn btn-primary" data-action="check-choice" ${lessonUI.selected==null||lessonUI.correct?'disabled':''}>Check answer</button>${lessonUI.correct?`<button class="btn btn-primary" data-action="${lessonUI.index===blocks.length-1?'complete-lesson':'next-block'}">${lessonUI.index===blocks.length-1?'Finish lesson':'Continue'} ${icon('arrow',18)}</button>`:''}</div>`:block.type==='practice'?`<button class="btn btn-primary" data-action="practice-done">${lessonUI.index===blocks.length-1?'I tried this · Finish lesson':'I tried this'} ${icon('arrow',18)}</button>`:lessonUI.index===blocks.length-1?`<button class="btn btn-primary" data-action="complete-lesson">Finish lesson ${icon('arrow',18)}</button>`:`<button class="btn btn-primary" data-action="next-block">Continue ${icon('arrow',18)}</button>`}</div>`}</article></div>`,'Lesson · '+item.title)}
function blockMarkup(block,item){const e=escapeHtml;
  if(block.type==='insight')return `<span class="eyebrow">Take this with you</span><p class="lesson-lead">${e(block.summary)}</p><ol class="step-list">${block.steps.map((step,i)=>`<li><b>${i+1}</b><span>${e(step)}</span></li>`).join('')}</ol>`;
  if(block.type==='activity-intro')return `<span class="eyebrow">Your camera activity</span><h2>Watch it, then try it</h2><p class="lesson-lead">${e(item.cameraPrompt||block.summary)}</p>${motionGuide(item)}<details class="technique-tips"><summary>Step-by-step tips</summary><ol class="step-list">${block.steps.map((step,i)=>`<li><b>${i+1}</b><span>${e(step)}</span></li>`).join('')}</ol></details>${block.cues?`<div class="activity-cue">${icon('shield',19)} ${e(block.cues.do)}</div>`:''}<p class="small muted">Practice slowly in clear space. Stop if you feel pain or dizziness.</p>`;
  if(block.type==='explanation')return `<span class="eyebrow">${item.id.startsWith('scenarios.')?'Why it matters':'Key idea'}</span><p class="lesson-lead">${e(block.text)}</p>${block.detail?`<p class="muted">${e(block.detail)}</p>`:''}`;
  if(block.type==='steps')return `<h2>${e(block.heading)}</h2>${item.mode==='movement'?'<p class="privacy">Practice slowly in clear space. Stop if you feel pain or dizziness.</p>':''}${item.mode==='partner'?'<p class="privacy">Any partner drill requires consent, gentle pressure, and supervision. No camera score is offered for partner contact.</p>':''}<ol class="step-list">${block.items.map((step,i)=>`<li><b>${i+1}</b><span>${e(step)}</span></li>`).join('')}</ol>`;
  if(block.type==='demonstration'){const frame=block.frames[lessonUI.demoIndex||0];return `<h2>${e(block.heading)}</h2><div class="demo-wrap"><div class="demo-art" aria-hidden="true"><div class="demo-person pose-${e(frame.pose)}"><i class="head"></i><i class="torso"></i><i class="arm left"></i><i class="arm right"></i><i class="forearm left"></i><i class="forearm right"></i><i class="leg left"></i><i class="leg right"></i></div><span class="floor-arrow">${frame.pose==='step'?'→':'⌁'}</span></div><div class="demo-copy"><span class="chip">Stage ${(lessonUI.demoIndex||0)+1} of ${block.frames.length}</span><h3>${e(frame.label)}</h3><p>${e(frame.text)}</p><div class="demo-tabs" role="group" aria-label="Demonstration stages">${block.frames.map((stage,i)=>`<button class="demo-tab" data-action="demo-stage" data-index="${i}" aria-pressed="${(lessonUI.demoIndex||0)===i}">${i+1}. ${e(stage.label)}</button>`).join('')}</div></div></div><p class="small muted">This diagram is an approximate front view. Move only within a comfortable range.</p>`}
  if(block.type==='cues')return `<span class="eyebrow">Check your form</span><h2>${e(block.heading)}</h2><div class="cue-grid"><div class="cue-card"><span class="chip good">Helpful cue</span><p>${e(block.do)}</p></div><div class="cue-card"><span class="chip">Watch for</span><p>${e(block.avoid)}</p></div></div>`;
  if(block.type==='visual')return `<span class="eyebrow">See the sequence</span><h2>${e(block.heading)}</h2><div class="visual-route" aria-label="${e(block.labels.join(' then '))}">${block.labels.map((label,i)=>`${i?'<i aria-hidden="true">→</i>':''}<span>${e(label)}</span>`).join('')}</div><p class="muted">Notice the path before you need it. A clear route matters more than a perfect move.</p>`;
  if(block.type==='practice')return `<h2>${e(block.heading)}</h2><div class="practice-panel"><p>${e(block.text)}</p></div>`;
  if(block.type==='choice')return `<span class="eyebrow">Quick decision</span><h2>${e(block.prompt)}</h2><div class="choice-list" role="group" aria-label="Choose one answer">${block.options.map((option,i)=>`<button class="choice-option ${lessonUI.selected===i?'selected':''} ${lessonUI.answered&&lessonUI.selected===i?(lessonUI.correct?'correct':'wrong'):''}" data-action="select-choice" data-index="${i}" ${lessonUI.correct?'disabled':''}>${e(option)}</button>`).join('')}</div>${lessonUI.answered?`<div class="feedback ${lessonUI.correct?'':'error'}" role="status"><strong>${lessonUI.correct?'Good decision.':'Try another option.'}</strong><br>${e(block.why)}</div>`:''}`;
  return `<span class="eyebrow">Remember</span><h2>${e(block.heading)}</h2><p style="font-size:1.2rem">${e(block.text)}</p><div class="privacy">The goal is to reduce risk and reach help. No technique guarantees safety.</div>`;
}
async function completeLesson(item){
  if(!hasPassedDecision(state.attempts,item)){
    lessonUI.index=lessonBlocks(item).findIndex(block=>block.type==='choice');
    lessonUI.selected=null;lessonUI.answered=false;lessonUI.correct=false;
    toast('Answer the quick decision to finish this lesson.');render();return;
  }
  const before=totals(),awardsBefore=achievementSnapshot(),goal=state.profile?.daily_goal||1;
  const today=()=>state.days.find(x=>x.activity_date===new Date().toLocaleDateString('en-CA'))?.lessons_completed||0;
  const todayBefore=today();
  const cameraPass=state.attempts.some(a=>a.lesson_id===item.id&&a.kind==='camera'&&a.passed&&a.score>=80);
  const outcome=await saveLesson(item.id,cameraPass?'mastered':'passed');
  clearPlace(state.user.id,item);
  lastCompletion={id:item.id,xp:outcome.xp,mastery:cameraPass&&before.mastered<totals().mastered,dailyGoal:todayBefore<goal&&today()>=goal,unitComplete:unitById.get(item.unitId).lessons.every(x=>completed(x.id)),first:before.completed===0&&outcome.xp>0};
  lessonUI=null;
  go('/complete/'+item.id);
  showAchievementToasts(awardsBefore);
}
function completionPage(id){const item=lessonById.get(id);if(!item)return notFound();const next=lessons[lessons.indexOf(item)+1],milestones=lastCompletion?.id===id?lastCompletion:null,t=totals(),unit=unitById.get(item.unitId);return shell(`<section class="completion-card"><div class="completion-emblem">${icon(milestones?.mastery?'star':'shield',48)}</div><span class="eyebrow">${milestones?.unitComplete?'Unit complete':milestones?.mastery?'Skill mastered':'Lesson complete'}</span><h1>${milestones?.unitComplete?'A whole unit behind you.':'That is one more skill you can use.'}</h1><p>${escapeHtml(item.title)} is complete. ${next?`Next: ${escapeHtml(next.title)}.`:'You have reached the end of this path.'}</p><div class="reward-strip"><div>${icon('spark',23)}<strong>${milestones?.xp?`+${milestones.xp} XP`:`${t.xp} XP`}</strong><span>${milestones?.xp?'earned now':'earned so far'}</span></div><div>${icon('path',23)}<strong>${t.completed} / ${lessons.length}</strong><span>lessons complete</span></div></div>${milestones?.first||milestones?.dailyGoal||milestones?.mastery||milestones?.unitComplete?`<div class="milestone-list">${milestones.first?`<div>${icon('trophy',20)} First lesson award unlocked</div>`:''}${milestones.dailyGoal?`<div>${icon('target',20)} Daily goal reached</div>`:''}${milestones.mastery?`<div>${icon('star',20)} Camera skill mastered</div>`:''}${milestones.unitComplete?`<div>${icon('shield',20)} ${escapeHtml(unit.title)} complete</div>`:''}</div>`:''}<div class="completion-actions">${next?`<a class="btn btn-primary btn-lg" href="#/lesson/${next.id}">Next lesson ${icon('arrow',18)}</a>`:`<a class="btn btn-primary btn-lg" href="#/path">Explore your path ${icon('arrow',18)}</a>`}${item.assessmentId?`<a class="btn btn-soft" href="#/camera/${id}">Practice with camera ${icon('camera',18)}</a>`:''}<a class="btn btn-tertiary" href="#/path">Back to path</a></div></section>`,'Lesson complete')}
function progressPage(){const t=totals(),goal=state.profile?.daily_goal||1,daily=state.days.find(x=>x.activity_date===new Date().toLocaleDateString('en-CA'))?.lessons_completed||0,next=nextLesson();return shell(`<div class="progress-page"><header class="page-intro"><span class="eyebrow">Your progress</span><h1>Look how far you have come.</h1><p>Every finished lesson is another useful choice you can carry into everyday life.</p></header><div class="progress-hero"><div><span class="eyebrow">Learning journey</span><strong>${t.completed}<small> / ${lessons.length}</small></strong><span>lessons complete</span><div class="progress-track"><div class="progress-fill" style="width:${percent(t.completed,lessons.length)}%"></div></div></div><div class="progress-hero-side"><div>${icon('spark',22)} <b>${t.xp} XP</b><span>earned</span></div><div>${icon('flame',22)} <b>${t.streak} ${t.streak===1?'day':'days'}</b><span>current streak</span></div><div>${icon('star',22)} <b>${t.mastered}</b><span>camera skills mastered</span></div></div></div><div class="progress-columns"><section class="card"><div class="section-heading"><div><span class="eyebrow">Your units</span><h2>Step by step</h2></div><a class="text-link" href="#/path">Open path ${icon('arrow',17)}</a></div><div class="unit-progress-list">${units.map((unit,i)=>{const n=unit.lessons.filter(x=>completed(x.id)).length;return `<a href="#/unit/${unit.id}"><span class="unit-progress-number">${i+1}</span><span class="unit-progress-copy"><strong>${escapeHtml(unit.title)}</strong><span class="progress-track"><span class="progress-fill" style="width:${percent(n,unit.lessons.length)}%"></span></span></span><span class="unit-progress-count">${n}/${unit.lessons.length}</span></a>`}).join('')}</div></section><aside class="progress-side"><section class="card"><span class="eyebrow">Today</span><h3>${daily>=goal?'Daily goal complete':'Keep your streak going'}</h3><p>${Math.min(daily,goal)} of ${goal} lesson${goal===1?'':'s'} today</p><div class="progress-track"><div class="progress-fill" style="width:${percent(Math.min(daily,goal),goal)}%"></div></div><a class="btn btn-soft" href="#/lesson/${next.id}">${learningAction(next)} ${icon('arrow',17)}</a></section><section class="card"><span class="eyebrow">Milestones</span><h3>Good work deserves a moment.</h3><p>See the awards you have earned through steady practice.</p><a class="text-link" href="#/achievements">View awards ${icon('arrow',17)}</a></section></aside></div></div>`,'Progress')}
function achievementsPage(){
  const stats=achievementStats(state.progress,state.days,totals());
  const earned=earnedAchievementIds(stats);
  const groups=['Learning','Camera practice','Consistency'];
  const cards=category=>ACHIEVEMENTS.filter(award=>award.category===category).map(award=>{
    const current=Math.min(award.value(stats),award.target),has=earned.has(award.id);
    return `<article class="badge ${has?'earned':'locked'} tone-${award.tone}"><div class="badge-top"><span class="badge-symbol" aria-hidden="true">${icon(award.icon,31)}</span>${has?`<span class="badge-check" aria-label="Earned">${icon('check',16)}</span>`:''}</div><div><h3>${escapeHtml(award.title)}</h3><p>${escapeHtml(award.description)}</p></div><div class="badge-foot"><span class="badge-state">${has?'Earned':`${current} of ${award.target}`}</span><span class="badge-meter" role="progressbar" aria-label="${escapeHtml(award.title)} progress" aria-valuenow="${current}" aria-valuemin="0" aria-valuemax="${award.target}"><i style="width:${percent(current,award.target)}%"></i></span></div></article>`;
  }).join('');
  return shell(`<div class="awards-page"><a class="text-link back-link" href="#/progress">${icon('back',17)} Back to progress</a><header class="page-intro awards-head"><span class="eyebrow">Your achievements</span><h1>Every step has a story.</h1><p>Earn awards for learning, camera practice, and returning to your skills.</p><span class="chip good">${earned.size} of ${ACHIEVEMENTS.length} earned</span></header>${groups.map(category=>`<section class="award-group"><div class="section-heading"><div><span class="eyebrow">${category}</span><h2>${category==='Learning'?'Build your foundation':category==='Camera practice'?'Put skills into motion':'Keep showing up'}</h2></div></div><div class="badge-grid">${cards(category)}</div></section>`).join('')}</div>`,'Awards');
}
function settingsPage(){const p=state.profile,cal=calibrationForDevice(),device=getDeviceClass()==='mobile'?'Mobile':'Desktop',quality=cal?.quality>=90?'Excellent tracking':cal?.quality>=75?'Good tracking':'Ready to practice';return shell(`<div class="settings-page"><header class="page-intro"><span class="eyebrow">Your space</span><h1>Profile & settings</h1><p>Make the learning pace and camera setup work for you.</p></header><div class="settings-grid"><section class="card"><div class="card-heading">${icon('user',24)}<div><span class="eyebrow">Your profile</span><h2>Make it yours</h2></div></div><form id="settings-form" class="form"><div class="field"><label for="display-name">Name</label><input id="display-name" name="name" maxlength="60" required value="${escapeHtml(p.display_name)}"></div><div class="field"><label for="daily-goal">Daily goal</label><select id="daily-goal" name="goal">${[1,2,3,4,5].map(x=>`<option value="${x}" ${p.daily_goal===x?'selected':''}>${x} lesson${x===1?'':'s'} a day</option>`).join('')}</select><small>Choose a pace that feels easy to return to.</small></div><button class="btn btn-primary" type="submit">Save changes</button></form><div class="account-row"><span>Signed in as<br><strong>${escapeHtml(state.user.email)}</strong></span><button class="btn btn-ghost" data-action="signout">Sign out</button></div></section><div class="settings-side"><section class="card"><div class="card-heading">${icon('camera',24)}<div><span class="eyebrow">Camera practice</span><h2>Camera setup</h2></div></div><div class="calibration-status"><span class="device-mark">${icon(device==='Mobile'?'phone':'laptop',25)}</span><span><strong>${device} calibration</strong><small>${cal?`Ready to practice · ${quality}`:'Set up when you reach a camera lesson'}</small></span>${cal?icon('check',21):''}</div><div class="settings-actions"><a class="btn btn-soft" href="#/calibrate">${cal?'Refresh calibration':'Set up camera'}</a>${cal?'<button class="btn btn-danger" data-action="delete-calibration">Remove setup</button>':''}</div><details class="camera-details"><summary>Camera & privacy details</summary><p>Your video stays in your browser. Your account stores derived body proportions and assessment results, never footage.</p>${cal?`<p>Tracking quality from your last setup: ${cal.quality} of 100.</p>`:''}</details></section><section class="card install-card"><div class="card-heading">${icon('phone',24)}<div><span class="eyebrow">Take RakshaOne with you</span><h2>Install the app</h2></div></div><p>Open it from your home screen whenever you have a few minutes to learn.</p>${deferredInstall?'<button class="btn btn-soft" data-action="install">Install RakshaOne</button>':'<p class="small muted">Use your browser’s Add to Home Screen option when available.</p>'}</section></div></div></div>`,'Settings')}
function notFound(){return shell(`<section class="card"><h1>That page is not here.</h1><p>Return to the learning path and choose a lesson.</p><a class="btn btn-primary" href="#/path">Open learning path</a></section>`,'Page not found')}

function authPage(mode){const signup=mode==='signup',reset=mode==='reset';return `<div class="auth-wrap"><section class="auth-story">${brand()}<span class="eyebrow">Practical safety, one step at a time</span><h1>Learn to notice. Choose. Move. Get help.</h1><p>RakshaOne gives you short lessons, realistic decisions, and private movement coaching to build safer habits.</p><div class="auth-points"><div><b>01</b> Calm, useful learning for everyday situations</div><div><b>02</b> Solo-first practice and clear safety guidance</div><div><b>03</b> Camera analysis stays on your device</div></div></section><section class="auth-panel"><div class="auth-box"><span class="eyebrow">${reset?'Account help':signup?'Start learning':'Welcome back'}</span><h2>${reset?'Reset your password':signup?'Create your account':'Sign in to continue'}</h2><p class="muted">${reset?'We will email you a reset link.':signup?'A safer choice starts here.':'Pick up exactly where you left off.'}</p><form id="auth-form" data-mode="${mode}" class="form"><div class="field"><label for="auth-email">Email</label><input id="auth-email" name="email" type="email" autocomplete="email" required placeholder="you@example.com"></div>${reset?'':`<div class="field"><label for="auth-password">Password</label><input id="auth-password" name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" minlength="8" required placeholder="At least 8 characters"></div>`}<p id="auth-message" role="status" style="display:none"></p><button type="submit" class="btn btn-primary">${reset?'Send reset link':signup?'Create account':'Sign in'}</button></form><div style="margin-top:22px">${reset?'<a class="text-link" href="#/signin">Back to sign in</a>':signup?'Already have an account? <a class="text-link" href="#/signin">Sign in</a>':'New here? <a class="text-link" href="#/signup">Create an account</a><br><a class="text-link" href="#/reset">Forgot password?</a>'}</div><p class="small muted" style="margin-top:35px">Personal safety skills reduce risk; no technique guarantees protection.</p></div></section></div>`}
function onboardingPage(){return shell(`<section class="card" style="max-width:680px;margin:35px auto;padding:36px"><span class="eyebrow">One quick introduction</span><h1>Let's make this yours.</h1><p class="muted">A name and a small daily goal are enough to begin. Camera setup can wait until your first camera activity.</p><form id="onboarding-form" class="form"><div class="field"><label for="onboard-name">What should we call you?</label><input id="onboard-name" name="name" maxlength="60" required placeholder="Your first name" value="${escapeHtml(state.user?.user_metadata?.name||'')}"></div><div class="field"><label for="onboard-goal">A comfortable daily goal</label><select id="onboard-goal" name="goal"><option value="1">1 lesson a day</option><option value="2">2 lessons a day</option><option value="3">3 lessons a day</option></select></div><div class="privacy">Our approach: avoid → de-escalate → create distance → escape → get help. Physical practice is optional and should feel controlled.</div><button type="submit" class="btn btn-primary">Begin learning →</button></form></section>`,'Getting started')}
function newPasswordPage(){return shell(`<section class="card" style="max-width:580px;margin:35px auto"><span class="eyebrow">Account recovery</span><h1>Choose a new password.</h1><p class="muted">Use at least eight characters. Your learning progress will stay with your account.</p><form id="new-password-form" class="form"><div class="field"><label for="new-password">New password</label><input id="new-password" name="password" type="password" autocomplete="new-password" minlength="8" required></div><button class="btn btn-primary" type="submit">Update password</button></form></section>`,'Password reset')}
function cameraFrame(){return `<div class="camera-stage"><video id="pose-video" autoplay muted playsinline aria-label="Live camera preview"></video><canvas id="pose-canvas" aria-label="Live pose and target alignment overlay"></canvas><div class="camera-placeholder" id="camera-placeholder"><img src="./assets/logo.png" alt=""></div><div class="camera-overlay"><span id="camera-live-status">Camera off</span><span>Private on this device</span></div><div class="camera-distance-cue" id="camera-distance-cue" aria-hidden="true">Step back until your whole body fits.</div></div>`}
function calibrationPage(fromId){const cal=calibrationForDevice(),device=getDeviceClass()==='mobile'?'Mobile':'Desktop',back=fromId?`/lesson/${fromId}`:'/settings';return shell(`<div class="camera-page"><a class="text-link back-link" href="#${back}">${icon('back',17)} ${fromId?'Back to lesson':'Back to settings'}</a><header class="page-intro"><span class="eyebrow">Camera setup · ${device}</span><h1>Find your frame.</h1><p>Start the camera while nearby, then step back. Both positions save automatically after a short hold.</p></header><div class="camera-layout"><div class="camera-main">${cameraFrame()}<div class="camera-controls"><button class="btn btn-primary" data-action="start-calibration">Start camera</button><button class="btn btn-secondary" data-action="switch-camera">Switch camera</button><button class="btn btn-ghost" data-action="stop-camera">Stop</button></div></div><aside class="card camera-guide"><span class="eyebrow">Two gentle positions</span><h2 id="score-heading">Get ready</h2><p id="camera-message" role="status">Step into full view. Stand naturally, then open your arms when prompted.</p><ol class="calibration-steps"><li id="cal-step-neutral"><span>1</span><div><strong>Stand naturally</strong><small>Relax your arms and hold still.</small></div></li><li id="cal-step-arms"><span>2</span><div><strong>Open your arms</strong><small>Raise them out to the sides if comfortable.</small></div></li></ol><details class="camera-details manual-capture"><summary>Need to save a pose manually?</summary><div id="calibration-actions" class="calibration-actions"><button class="btn btn-secondary" data-action="capture-neutral" disabled>Save standing pose</button><button class="btn btn-secondary" data-action="capture-arms" disabled>Save arms-out pose</button></div></details><details class="camera-details"><summary>Privacy and setup details</summary><p>Camera frames stay on this device. We save body proportions and a tracking quality score to your account.</p>${cal?`<p>Previous ${device} setup quality: ${cal.quality} of 100.</p>`:''}</details></aside></div></div>`,'Camera setup')}
function calibrationReadyPage(fromId){const device=getDeviceClass()==='mobile'?'Mobile':'Desktop',cal=calibrationForDevice();if(!cal)return shell(`<section class="card empty-state">${icon('camera',36)}<h1>Camera setup is not finished.</h1><p>Complete the two guided positions to start practice.</p><a class="btn btn-primary" href="#/calibrate/${fromId||''}">Return to setup</a></section>`,'Camera setup');return shell(`<section class="completion-card setup-complete"><div class="completion-emblem">${icon('check',48)}</div><span class="eyebrow">Camera setup complete</span><h1>You are ready to train.</h1><p>Your ${device.toLowerCase()} camera is ready for guided practice.</p><div class="calibration-status"><span class="device-mark">${icon(device==='Mobile'?'phone':'laptop',25)}</span><span><strong>${device} calibration</strong><small>${cal?.quality>=90?'Excellent tracking':cal?.quality>=75?'Good tracking':'Ready to practice'}</small></span></div><div class="completion-actions"><a class="btn btn-primary btn-lg" href="#${fromId?`/camera/${fromId}`:'/path'}">${fromId?'Start practicing':'Continue learning'} ${icon('arrow',18)}</a><a class="btn btn-tertiary" href="#${fromId?`/lesson/${fromId}`:'/settings'}">${fromId?'Back to lesson':'Back to settings'}</a></div></section>`,'Camera ready')}
function cameraPage(id){const item=lessonById.get(id);if(!item?.assessmentId)return notFound();const config=ASSESSMENTS[item.assessmentId],cal=calibrationForDevice();if(!cal)return shell(`<section class="camera-entry card"><span class="step-art">${icon('camera',42)}</span><span class="eyebrow">Before camera practice</span><h1>Set up this camera once.</h1><p>We will help you find a clear full-body view, then bring you straight back to ${escapeHtml(item.title)}.</p><div class="completion-actions"><a class="btn btn-primary btn-lg" href="#/calibrate/${id}">Set up camera ${icon('arrow',18)}</a><a class="btn btn-tertiary" href="#/lesson/${id}">Back to lesson</a></div></section>`,'Camera setup');return shell(`<div class="camera-page practice-page"><a class="text-link back-link" href="#/lesson/${id}">${icon('back',17)} Back to lesson</a><header class="page-intro"><span class="eyebrow">${escapeHtml(item.title)} · Camera practice</span><h1>${escapeHtml(config.title)}</h1><p>${escapeHtml(config.view)} ${escapeHtml(config.target)}</p></header><div class="camera-layout"><div class="camera-main">${cameraFrame()}<div class="camera-controls"><button class="btn btn-primary" data-action="start-assessment">Start practice</button><button class="btn btn-secondary" data-action="switch-camera">Switch camera</button><button class="btn btn-ghost" data-action="stop-camera">Stop</button></div><a class="text-link camera-reset" href="#/calibrate/${id}">Refresh camera setup ${icon('arrow',16)}</a></div><aside class="card camera-guide"><span class="eyebrow">Live guidance</span><h2 id="score-heading">Get into position</h2><p id="camera-message" role="status">Start practice, then follow the movement cues. A steady hold finishes automatically.</p><div class="phase-chip" id="phase-chip">${config.kind==='dynamic'?'Get ready':'Hold a comfortable position'}</div><div class="primary-correction" id="correction-box" aria-live="polite">A guide on screen will show the target position. Move slowly and comfortably.</div><div class="auto-complete-hint">${icon('check',20)} Your result saves after a steady hold.</div><details class="camera-details"><summary>See tracking details</summary><div id="criteria-list"><p>Tracking details appear once practice begins.</p></div><p>A camera score reflects visible body position. It cannot predict real-world safety.</p></details></aside></div></div>`,'Camera practice')}
function assessmentResultPage(id){const item=lessonById.get(id),saved=state.attempts.find(a=>a.lesson_id===id&&a.kind==='camera'),config=ASSESSMENTS[item?.assessmentId],result=lastCompletion?.id===id&&lastCompletion.assessment?lastCompletion.assessment:saved?{score:saved.score,criteria:config.criteria.map(rule=>({label:rule.label,score:saved.criteria?.scores?.[rule.id]??0,status:(saved.criteria?.scores?.[rule.id]??0)>=80?'good':'needs work'})),corrections:saved.criteria?.corrections||[]}:null;if(!item||!result)return shell(`<section class="card empty-state">${icon('camera',36)}<h1>No camera practice yet.</h1><p>Return to the lesson whenever you are ready.</p><a class="btn btn-primary" href="#/lesson/${id}">Back to lesson</a></section>`,'Camera result');const mastered=state.progress.get(id)?.status==='mastered',bonus=lastCompletion?.id===id?lastCompletion.xp:0;return shell(`<div class="result-layout"><section class="completion-card result-complete"><div class="completion-emblem">${icon(mastered?'star':'check',45)}</div><span class="eyebrow">${mastered?'Camera skill mastered':'Camera practice complete'}</span><h1>${mastered?'Your practice paid off.':'Strong work. Keep it controlled.'}</h1><p>${mastered?`You met the visible movement criteria for ${escapeHtml(item.title)}. Keep the skill gentle and repeatable.`:`You met the visible movement criteria for ${escapeHtml(item.title)}. Return to the lesson to check the decision behind it.`}</p><div class="result-score">${result.score}<span> / 100</span></div>${bonus?`<span class="chip good">${icon('spark',18)} +${bonus} XP earned</span>`:''}<div class="completion-actions"><a class="btn btn-primary btn-lg" href="#${mastered?'/path':`/lesson/${id}`}">${mastered?'Back to path':'Continue lesson'} ${icon('arrow',18)}</a><a class="btn btn-tertiary" href="#/camera/${id}">Practice again</a></div></section><aside class="card result-detail"><span class="eyebrow">What went well</span><h2>Your movement check</h2>${result.criteria.map(c=>`<div class="criterion"><strong>${escapeHtml(c.label)}</strong><span>${c.score>=80?'Looking good':'Keep practicing'}</span><div class="mini-track"><i style="width:${c.score}%"></i></div></div>`).join('')}<div class="primary-correction"><strong>One cue to remember</strong><p>${escapeHtml(result.corrections[0]||'Stay relaxed, balanced, and ready to move toward safety.')}</p></div></aside></div>`,'Camera result')}

async function render(){const path=route();if(currentRoute!==path){stopCamera();currentRoute=path;window.scrollTo({top:0,behavior:'instant'})}if(state.loading){app.innerHTML='<div class="boot"><img src="./assets/logo.png" alt="RakshaOne"><p>Preparing your learning space…</p></div>';return}
  if(!state.user){app.innerHTML=authPage(path==='/signup'?'signup':path==='/reset'?'reset':'signin');return}
  if(path==='/new-password'){app.innerHTML=newPasswordPage();return}
  if(!state.profile?.onboarding_complete){app.innerHTML=onboardingPage();return}
  const parts=path.split('/').filter(Boolean);
  app.innerHTML=path==='/home'?home():path==='/path'?pathPage():parts[0]==='unit'?unitPage(parts[1]):parts[0]==='lesson'?lessonPage(parts[1]):parts[0]==='complete'?completionPage(parts[1]):parts[0]==='camera'?cameraPage(parts[1]):parts[0]==='assessment'?assessmentResultPage(parts[1]):parts[0]==='calibration-ready'?calibrationReadyPage(parts[1]):path==='/progress'?progressPage():path==='/achievements'?achievementsPage():path==='/settings'?settingsPage():parts[0]==='calibrate'?calibrationPage(parts[1]):notFound();
}

document.addEventListener('submit',async event=>{
  const form=event.target;if(!['auth-form','onboarding-form','settings-form','new-password-form'].includes(form.id))return;
  event.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;button.classList.add('is-loading');button.setAttribute('aria-busy','true');
  try{
    if(form.id==='auth-form'){
      const email=form.elements.namedItem('email').value.trim(),mode=form.dataset.mode;
      const password=form.elements.namedItem('password')?.value;
      const response=mode==='signup'?await db.auth.signUp({email,password}):mode==='reset'?await db.auth.resetPasswordForEmail(email,{redirectTo:location.href.split('#')[0]}):await db.auth.signInWithPassword({email,password});
      if(response.error)throw response.error;
      if(mode==='reset'||mode==='signup'&&!response.data?.session){const msg=document.getElementById('auth-message');msg.className='success-line';msg.textContent=mode==='reset'?'Check your email for a password reset link.':'Account created. If confirmation is enabled on this project, check your email to continue.';msg.style.display='block'}
      else{await loadAccount();go('/home')}
    }else if(form.id==='new-password-form'){const {error}=await db.auth.updateUser({password:form.elements.namedItem('password').value});if(error)throw error;recovering=false;toast('Password updated.');go('/settings')}
    else if(form.id==='onboarding-form'){await saveProfile({display_name:form.elements.namedItem('name').value.trim(),daily_goal:Number(form.elements.namedItem('goal').value),onboarding_complete:true});go('/home')}
    else{await saveProfile({display_name:form.elements.namedItem('name').value.trim(),daily_goal:Number(form.elements.namedItem('goal').value),onboarding_complete:true});toast('Settings saved.');render()}
  }catch(error){const msg=document.getElementById('auth-message');if(msg){msg.className='error-line';msg.textContent=friendlyError(error);msg.style.display='block'}else toast('Changes could not be saved. Please try again.')}finally{button.disabled=false;button.classList.remove('is-loading');button.removeAttribute('aria-busy')}
});

document.addEventListener('click',async event=>{
  const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;
  const saving=['check-choice','practice-done','complete-lesson','capture-arms','delete-calibration'].includes(action);
  if(saving){if(button.disabled)return;button.disabled=true;button.classList.add('is-loading');button.setAttribute('aria-busy','true')}
  try{
    if(action==='select-choice'){lessonUI.selected=Number(button.dataset.index);lessonUI.answered=false;render();return}
    if(action==='demo-stage'){lessonUI.demoIndex=Number(button.dataset.index);render();return}
    if(action==='previous-block'){lessonUI.index=Math.max(0,lessonUI.index-1);lessonUI.selected=null;lessonUI.answered=false;lessonUI.correct=false;render();return}
    if(action==='next-block'||action==='skip-camera'){lessonUI.index=Math.min(lessonBlocks(lessonById.get(lessonUI.id)).length-1,lessonUI.index+1);lessonUI.selected=null;lessonUI.answered=false;lessonUI.correct=false;render();return}
    if(action==='check-choice'){const item=lessonById.get(lessonUI.id),block=lessonBlocks(item)[lessonUI.index];lessonUI.answered=true;lessonUI.correct=lessonUI.selected===block.answer;await recordAttempt(item.id,item.id+'.'+block.id,'quiz',lessonUI.correct?100:0,lessonUI.correct,{selected:lessonUI.selected});render();return}
    if(action==='practice-done'){const item=lessonById.get(lessonUI.id),last=lessonUI.index===lessonBlocks(item).length-1;await recordAttempt(item.id,item.id+'.practice','guided',null,true);if(last)await completeLesson(item);else{await saveLesson(item.id,'practiced');lessonUI.index++;render()}return}
    if(action==='complete-lesson'){await completeLesson(lessonById.get(lessonUI.id));return}
    if(action==='signout'){stopCamera();const {error}=await db.auth.signOut();if(error)throw error;state.user=null;state.profile=null;state.progress.clear();lessonUI=null;lastCompletion=null;go('/signin');return}
    if(action==='delete-calibration'){await removeCalibration(getDeviceId());toast('Calibration deleted from this device profile.');render();return}
    if(action==='install'&&deferredInstall){await deferredInstall.prompt();deferredInstall=null;render();return}
    if(action==='stop-camera'){stopCamera();cameraStatus('Camera stopped.');return}
    if(action==='switch-camera'){const next=window.__facing==='environment'?'user':'environment';window.__facing=next;const calibration=route().startsWith('/calibrate');await beginCamera(calibration,next);return}
    if(action==='start-calibration')return beginCamera(true,window.__facing||'user');
    if(action==='start-assessment')return beginCamera(false,window.__facing||'user');
    if(action==='capture-neutral')return captureCalibration('neutral');
    if(action==='capture-arms')return captureCalibration('arms');
  }catch(error){toast(friendlyError(error))}finally{if(saving&&button.isConnected){button.disabled=false;button.classList.remove('is-loading');button.removeAttribute('aria-busy')}}
});

function cameraStatus(message){if(message.startsWith('Pose tracking stopped'))message='Tracking paused. Start the camera again when you are ready.';if(message.startsWith('Loading private'))message='Preparing your camera guidance…';const el=document.getElementById('camera-message');if(el)el.textContent=message;const badge=document.getElementById('camera-live-status');if(badge)badge.textContent=message.startsWith('Camera could not')||message.startsWith('Tracking paused')?'Camera unavailable':camera?'Camera live':message.startsWith('Camera stopped')?'Camera off':message.startsWith('Requesting')?'Opening camera':'Camera ready';const distance=document.getElementById('camera-distance-cue');if(distance)distance.textContent=message}
let frame=null, neutralPose=null, face=null, bestResult=null, lastUiUpdate=0;
let neutralHoldSince=null, armsHoldSince=null, assessmentHoldSince=null;
let calibrationSaving=false, assessmentFinishing=false;
async function beginCamera(calibration,facingMode){
  stopCamera();
  const requestId=++cameraRequest;
  frame=null;neutralPose=null;bestResult=null;lastUiUpdate=0;calibrationSaving=false;assessmentFinishing=false;
  const id=route().split('/')[2],item=lessonById.get(id);
  const assessmentId=calibration?null:item?.assessmentId;
  const video=document.getElementById('pose-video'),canvas=document.getElementById('pose-canvas');
  if(!video||!canvas)return;
  cameraStatus('Requesting camera…');
  try{
    const started=await startPose({video,canvas,assessmentId,calibration:calibration?null:calibrationForDevice()?.metrics,facingMode,onStatus:cameraStatus,onFrame:data=>{
      if(requestId!==cameraRequest)return;
      frame=data;
      document.getElementById('camera-placeholder')?.remove();
      const now=performance.now();
      if(calibration){
        const valid=data.visibility.ok;
        const neutralButton=document.querySelector('[data-action=capture-neutral]');
        const armsButton=document.querySelector('[data-action=capture-arms]');
        if(neutralButton)neutralButton.disabled=!valid||!!neutralPose;
        if(armsButton)armsButton.disabled=!valid||!neutralPose||calibrationSaving;
        const candidate=valid&&(neutralPose?visibility(data.pose,'open_guard').ok&&armsOutReady(data.pose,neutralPose):neutralPoseReady(data.pose));
        const hold=heldFor(neutralPose?armsHoldSince:neutralHoldSince,candidate,now,1900);
        if(neutralPose)armsHoldSince=hold.since;else neutralHoldSince=hold.since;
        if(hold.ready&&!neutralPose){void captureCalibration('neutral');return}
        if(hold.ready&&neutralPose&&!calibrationSaving){armsHoldSince=null;void captureCalibration('arms').catch(error=>toast(friendlyError(error)));return}
        if(now-lastUiUpdate<250)return;
        lastUiUpdate=now;
        const message=!valid?data.visibility.message:candidate?`${neutralPose?'Arms open':'Standing still'} · ${Math.ceil(hold.remaining/1000)}`:neutralPose?'Open both arms to the sides.':'Stand naturally with arms relaxed.';
        cameraStatus(message);
        const heading=document.getElementById('score-heading');
        if(heading)heading.textContent=valid?neutralPose?'Step 2 of 2':'Step 1 of 2':'Find your full-body view';
        document.querySelector('.camera-stage')?.classList.toggle('is-success',candidate);
        return;
      }
      const result=data.result;
      if(!result||assessmentFinishing)return;
      const eligible=result.passed;
      const hold=heldFor(assessmentHoldSince,eligible,now,3000);
      assessmentHoldSince=hold.since;
      if(eligible&&(!bestResult||result.score>bestResult.score))bestResult=result;
      if(hold.ready){
        assessmentFinishing=true;
        cameraStatus('Practice complete. Saving your result…');
        void finishAssessment().catch(error=>{assessmentFinishing=false;toast('Result could not be saved. Please start practice again.');cameraStatus('Result could not be saved. Start practice again.')});
        return;
      }
      if(now-lastUiUpdate<250)return;
      lastUiUpdate=now;
      const movementPhase=data.session.phase;
      const config=ASSESSMENTS[assessmentId];
      const readyCue=['boundary_raise','cover_raise'].includes(assessmentId)?'Relax your arms at your sides and stand still.':assessmentId==='exit_turn'?'Face the camera and stand still.':'Stand still to get ready.';
      const message=eligible?`Hold steady · ${Math.ceil(hold.remaining/1000)}`:!result.valid?'Step back until your whole body is visible.':config.kind==='dynamic'&&movementPhase==='ready'?readyCue:config.kind==='dynamic'&&movementPhase==='gesture'?(config.moveCue||'Make the first movement.'):config.kind==='dynamic'&&movementPhase==='step'?(config.stepCue||'Move toward open space.'):config.kind==='dynamic'&&movementPhase==='move'?(config.moveCue||'Make one clear movement.'):result.corrections[0]||'Settle into a balanced finish.';
      cameraStatus(message);
      document.querySelector('.camera-stage')?.classList.toggle('is-success',eligible);
      const heading=document.getElementById('score-heading');
      if(heading)heading.textContent=eligible?'Finishing automatically':result.valid?'Keep adjusting':'Find your full-body view';
      const phase=document.getElementById('phase-chip');
      if(phase&&config.kind==='dynamic')phase.textContent=({ready:'Find your starting position',gesture:'Set your position',step:'Move to open space',move:'Make your move',settle:'Settle and hold'})[data.session.phase]||'Keep moving';
      const list=document.getElementById('criteria-list');
      if(list)list.innerHTML=result.valid?result.criteria.map(c=>`<div class="criterion"><strong>${escapeHtml(c.label)}</strong><span>${c.score}/100</span><div class="mini-track"><i style="width:${c.score}%"></i></div></div>`).join(''):'<p>Move until your whole body is visible.</p>';
      const correction=document.getElementById('correction-box');
      if(correction)correction.textContent=result.valid?(result.corrections[0]||'Good alignment. Keep breathing and stay balanced.'):'The camera needs a clearer full-body view.';
    }});
    if(requestId!==cameraRequest)started.stop();else camera=started;
  }catch(error){if(requestId===cameraRequest){cameraStatus('Camera could not open. Check camera permission and try again. Your lesson is saved.');const heading=document.getElementById('score-heading');if(heading)heading.textContent='Camera needs attention';toast('Camera could not start. Check permission and try again.')}}
}
async function captureCalibration(stage){
  if(!frame?.visibility.ok||!frame.pose){toast('Step back until your whole body is in view.');return}
  if(stage==='neutral'){
    if(neutralPose)return;
    neutralPose=frame.pose.map(p=>({...p}));
    neutralHoldSince=null;
    cameraStatus('Standing pose saved. Open your arms gently.');
    document.getElementById('cal-step-neutral')?.classList.add('done');
    document.getElementById('cal-step-arms')?.classList.add('active');
    const heading=document.getElementById('score-heading');if(heading)heading.textContent='One more position';
    return;
  }
  if(!neutralPose||calibrationSaving)return;
  const arms=frame.pose,armSeen=visibility(arms,'open_guard');
  if(!armSeen.ok){toast('Keep both wrists visible while your arms are out.');return}
  if(!armsOutReady(arms,neutralPose)){toast('Move your arms farther out to the sides, then try again.');return}
  const quality=Math.min(visibility(neutralPose).quality,armSeen.quality);
  const metrics=calibrationMetrics(neutralPose,arms,frame.video.videoWidth,frame.video.videoHeight);
  if(metrics.bodyHeight<0.3||metrics.shoulderWidth<0.04){toast('Move closer or adjust the camera so your body is clear.');return}
  calibrationSaving=true;
  cameraStatus('Both positions captured. Saving setup…');
  try{await saveCalibration(getDeviceId(),getDeviceClass(),metrics,quality);stopCamera();go('/calibration-ready/'+(route().split('/')[2]||''))}
  finally{calibrationSaving=false}
}
async function finishAssessment(){
  const id=route().split('/')[2],item=lessonById.get(id);
  if(!item||!bestResult)return;
  const result=bestResult,awardsBefore=achievementSnapshot();
  stopCamera();
  await recordAttempt(item.id,item.id+'.'+item.assessmentId,'camera',result.score,true,{scores:Object.fromEntries(result.criteria.map(c=>[c.id,c.score])),corrections:result.corrections,quality:result.quality});
  const outcome=await saveLesson(item.id,completed(id)?'mastered':'practiced',result.score);
  const checkIndex=lessonBlocks(item).findIndex(block=>block.type==='choice');
  if(lessonUI?.id===id){lessonUI.index=checkIndex;lessonUI.selected=null;lessonUI.answered=false;lessonUI.correct=false}
  savePlace(state.user.id,item,'check');
  lastCompletion={id,assessment:result,xp:outcome.xp,masteryEarned:outcome.masteryEarned};
  if(route()==='/camera/'+id)go('/assessment/'+id);
  showAchievementToasts(awardsBefore);
}

db.auth.onAuthStateChange((event)=>{if(event==='SIGNED_OUT'){stopCamera();recovering=false;state.user=null;state.profile=null;state.progress.clear();lessonUI=null;lastCompletion=null;render()}if(event==='PASSWORD_RECOVERY'){recovering=true;setTimeout(()=>loadAccount().then(()=>go('/new-password')).catch(error=>toast(error.message)),0)}});
loadAccount().then(()=>{if(!location.hash)location.hash='#/home';render()}).catch(error=>{state.loading=false;app.innerHTML=authPage('signin');toast('Could not load account: '+error.message)});
